//! 🖼️ Writes image dimensions, color provenance, independent ICC bytes and every ordered frame.
use semio_framework_value::{ValueError,ValueRefusalKind};
use super::{SemioImageSnapshot,SemioImageFrame,SemioImageMetadataEntry};
use crate::standards::v1::subsets::base::schema::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(super) fn encode(snapshot:&SemioImageSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode(encoding,"semio s.stdio.semio.image.dsl v1\n","s.stdio.semio.image.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn frame(value:&SemioImageFrame,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.fixed_u32(value.delay_ms,encoding)?;writer.delimiter(b",",encoding)?;writer.octets(&value.rgba8,encoding)?;writer.delimiter(b"]",encoding)}
fn entry(value:&SemioImageMetadataEntry,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.key,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.value,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioImageSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nwidth=",encoding)?;writer.fixed_u32(snapshot.width,encoding)?;writer.delimiter(b"\nheight=",encoding)?;writer.fixed_u32(snapshot.height,encoding)?;writer.delimiter(b"\ncolorspace=",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{super::colorspace_tag(snapshot.colorspace)}else{super::enc_colorspace(snapshot.colorspace)as u8})?;writer.delimiter(b"\nbitDepth=",encoding)?;if encoding==SnapshotEncoding::Binary{writer.byte(snapshot.bit_depth)?;}else{writer.integer(u64::from(snapshot.bit_depth),encoding)?;}writer.delimiter(b"\nicc=",encoding)?;match &snapshot.icc{Some(bytes)=>{if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"[1,")?;}writer.octets(bytes,encoding)?;writer.delimiter(b"]",encoding)?;},None=>if encoding==SnapshotEncoding::Binary{writer.byte(0)?;}else{writer.bytes(b"[0]")?;}}writer.delimiter(b"\nframes=",encoding)?;writer.list(&snapshot.frames,encoding,|writer,value|frame(value,writer,encoding))?;writer.delimiter(b"\nmetadata=",encoding)?;writer.list(&snapshot.metadata,encoding,|writer,value|entry(value,writer,encoding))}
